import{_ as o,o as e,c as r,a2 as s}from"./chunks/framework.RycU2wFZ.js";const p=JSON.parse('{"title":"ADR-002: 数据库选型全面升级至 PostgreSQL","description":"","frontmatter":{},"headers":[],"relativePath":"zh/specs/adr/002.md","filePath":"zh/specs/adr/002.md","lastUpdated":null}'),n={name:"zh/specs/adr/002.md"};function d(a,t,l,i,c,g){return e(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="adr-002-数据库选型全面升级至-postgresql" tabindex="-1">ADR-002: 数据库选型全面升级至 PostgreSQL <a class="header-anchor" href="#adr-002-数据库选型全面升级至-postgresql" aria-label="Permalink to &quot;ADR-002: 数据库选型全面升级至 PostgreSQL&quot;">​</a></h1><blockquote><p><strong>状态</strong>：<strong>已采纳 (Accepted)</strong><br><strong>决策者</strong>：AgentPay 架构团队 &amp; 业务主管<br><strong>日期</strong>：2026-10-18<br><strong>前置任务</strong>：T1.2 设计多租户逻辑数据模型<br><strong>废弃/演进</strong>：取代 Phase 0 仅依赖 SQLite 单机本地文件的做法</p></blockquote><hr><h2 id="_1-上下文与背景-context" tabindex="-1">1. 上下文与背景 (Context) <a class="header-anchor" href="#_1-上下文与背景-context" aria-label="Permalink to &quot;1. 上下文与背景 (Context)&quot;">​</a></h2><p>在 AgentPay Phase 0（Python 最小原型闭环阶段），系统主要为了追求极简的本地零依赖快速验证，采用了标准库的 SQLite（<code>sqlite3</code>）结合 WAL 模式和 <code>BEGIN IMMEDIATE</code> 悲观锁。</p><p>然而，随着项目正式向 <strong>多租户支付网关、Go 云原生高并发网关、Web 管理控制台与平台内部虚拟钱包账本（T1.7）</strong> 演进，数据层面临根本性的架构挑战：</p><ol><li><strong>多节点与集群水平扩展</strong>：Go Gateway 数据面与 Web 控制面需要部署多个实例（Pod）以实现高可用和无缝横向扩容。SQLite 基于本地文件系统，无法在无状态分布式容器集群中跨节点共享读写；</li><li><strong>虚拟钱包的高并发行级锁要求</strong>：平台内部虚拟钱包引入了资金冻结（Hold）与确权扣款（Capture）。SQLite 在写入事务时执行库级锁（Database-level Lock），高并发请求下极易产生 <code>sqlite3.OperationalError: database is locked</code>。而金融记账要求不同租户甚至同租户的不同账户之间互不阻塞，必须具备成熟的<strong>行级锁（Row-level Locking，如 <code>FOR UPDATE</code>）</strong>；</li><li><strong>海量审计事件与流水分区存储</strong>：消费记录（RequestRecord）、链上结算明细（SettlementRecord）与账本流水（LedgerEntry）属于高频时间序列数据，需要成熟的分区表（Partitioning）、高效 B-Tree 索引及复合唯一约束支持；</li><li><strong>配置版本快照与 JSONB 高性能操作</strong>：路由规则（Route）、安全策略（Policy）的发布需要记录不可变快照快查，PostgreSQL 的 <code>JSONB</code> 原生索引与检索能力极为出色。</li></ol><hr><h2 id="_2-决策-decision" tabindex="-1">2. 决策 (Decision) <a class="header-anchor" href="#_2-决策-decision" aria-label="Permalink to &quot;2. 决策 (Decision)&quot;">​</a></h2><p>我们正式决定：<strong>将 AgentPay 的生产核心数据存储全面选型为 PostgreSQL (&gt;= 15.0)</strong>。</p><p>具体落地规范如下：</p><ol><li><strong>统一数据中心</strong>：控制面管理服务、数据面 Go Gateway、虚拟钱包记账与消费审计统一接入 PostgreSQL 实例或主从集群；</li><li><strong>连接池与高并发管理</strong>：数据面 Go Gateway 采用 <code>pgxpool</code>，控制面 API 采用成熟的异步连接池，严格管理连接数与查询超时；</li><li><strong>强事务行级锁隔离</strong>： <ul><li>钱包扣费与冻结必须使用：<code>SELECT ... FROM ap_wallet WHERE wallet_id = $1 FOR UPDATE;</code></li><li>确保同一租户的并发扣费按序列化精确校验，不同租户的并发扣费完全并行无锁争用；</li></ul></li><li><strong>本地开发与轻量测试支持</strong>： <ul><li>仓库提供标准的 <code>docker-compose.yml</code> 一键拉起本地开发用 PostgreSQL；</li><li>纯算法/工具类的单元测试（如 x402 编解码、EIP-712 签名）保持零外部依赖，数据库相关集成测试在 CI/本地统一通过容器化 PostgreSQL 验证。</li></ul></li></ol><hr><h2 id="_3-方案对比与评估-options-considered" tabindex="-1">3. 方案对比与评估 (Options Considered) <a class="header-anchor" href="#_3-方案对比与评估-options-considered" aria-label="Permalink to &quot;3. 方案对比与评估 (Options Considered)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>评估维度</th><th>SQLite (原方案)</th><th>MySQL (8.0+)</th><th><strong>PostgreSQL (最终选择)</strong></th></tr></thead><tbody><tr><td><strong>并发锁粒度</strong></td><td>库级写锁（全局串行）</td><td>行级锁（InnoDB）</td><td><strong>行级锁（MVCC + FOR UPDATE 严密事务）</strong></td></tr><tr><td><strong>多节点共享</strong></td><td>不支持（仅单机文件）</td><td>原生支持</td><td><strong>原生支持（云原生 Operator/主从/连接池）</strong></td></tr><tr><td><strong>半结构化/JSON</strong></td><td>JSON1 文本函数</td><td>JSON 类型（支持局部操作）</td><td><strong>JSONB（二进制优化，支持 GIN 倒排索引）</strong></td></tr><tr><td><strong>金融记账与不变量</strong></td><td>约束功能基础</td><td>事务与约束支持完备</td><td><strong>极为严密（CHECK 约束、Partial Index、原生 UUID、强类型）</strong></td></tr><tr><td><strong>跨语言驱动支持</strong></td><td>各语言内嵌 C 绑定</td><td>成熟</td><td><strong>Go (<code>pgx</code>)、Python (<code>asyncpg</code>/<code>psycopg3</code>) 极高吞吐性能</strong></td></tr></tbody></table><hr><h2 id="_4-后续影响与执行要求-consequences" tabindex="-1">4. 后续影响与执行要求 (Consequences) <a class="header-anchor" href="#_4-后续影响与执行要求-consequences" aria-label="Permalink to &quot;4. 后续影响与执行要求 (Consequences)&quot;">​</a></h2><ol><li><strong>正向影响</strong>： <ul><li>彻底解除高并发吞吐瓶颈，满足网关数万 QPS 的读写能力；</li><li>虚拟钱包多租户并发安全从根本上得到数据库底层 ACID 保障；</li><li>支持不可变配置快照、全量操作审计与日终自动对账任务的大规模批量处理。</li></ul></li><li><strong>执行行动</strong>： <ul><li>编写多租户领域数据模型规范：<code>specs/multitenant-data-model.md</code>；</li><li>建立权威 DDL 脚本库：<code>infra/postgres/schema.sql</code>；</li><li>更新本地 <code>docker-compose.yml</code> 包含 PostgreSQL 基础服务配置。</li></ul></li></ol>',18)])])}const P=o(n,[["render",d]]);export{p as __pageData,P as default};
